block.css:
.quote {
  max-width: 46rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 2.5rem);
  border: 1px solid var(--cb-line);
  border-radius: var(--cb-radius);
  background: var(--cb-surface);
}
.quote__mark { display: block; margin-bottom: .5rem; color: var(--cb-accent); font-size: 2.5rem; line-height: 1; }
.quote__text { margin: 0; padding: 0; border: 0; font-size: clamp(1.15rem, 2.2vw, 1.4rem); line-height: 1.5; }
.quote__text p { margin: 0; }
.quote__by { display: flex; align-items: center; gap: 1rem; margin-top: 1.5rem; }
.quote__img { flex: none; width: 4.5rem; }
.quote__img img { display: block; width: 100%; height: auto; aspect-ratio: 1; object-fit: cover; border-radius: 50%; }
.quote__who { display: flex; flex-direction: column; }
.quote__name { font-weight: 700; }
.quote__role { color: var(--cb-muted); font-size: .95rem; }
